return ['domain'=>'zinn-translate','plural-forms'=>'nplurals=4; plural=((((n >= 2 && n <= 4)) && ((0 == 0))) ? 1 : ((((0 == 0)) == 0)) ? 2 : (((n == 1)) && ((0 == 0))) ? 0 : 3);','language'=>'cs_CZ','project-id-version'=>'zinn-translate','pot-creation-date'=>'2026-09-08T20:38:11+00:00','po-revision-date'=>'2026-09-08T20:38:11+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Translate'=>'Zinn® Translate','https://zinndigital.com/wordpress-plugins/zinn-translate'=>'https://zinndigital.com/wordpress-plugins/zinn-translate','Publishes this site in every language you choose, on its own web addresses, with translated slugs, metadata, menus, WooCommerce products, hreflang, per-language sitemaps and llms.txt. Translate with your Zinn Digital® plan or with your own provider key.'=>'Publikuje tento web v každém zvoleném jazyce na vlastních webových adresách s přeloženými slugy, metadaty, menu, produkty WooCommerce, značkami hreflang, mapami stránek pro jednotlivé jazyky a souborem llms.txt. Překládejte v rámci svého tarifu Zinn Digital® nebo pomocí vlastního klíče poskytovatele.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'Uloženo. Zadejte novou hodnotu pro přepsání.','Filter this list…'=>'Filtrovat tento seznam…','Filter this list'=>'Filtrovat tento seznam','Nothing matches that filter.'=>'T tomuto filtru nic neodpovídá.','Add a row'=>'Přidat řádek','Remove this row'=>'Odstranit tento řádek','Remove'=>'Odebrat','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — přehled','Overview'=>'Přehled','Every Zinn® plugin on this site, and whether it is working.'=>'Každý plugin Zinn® na tomto webu a zda funguje.','No connection is needed for this plugin.'=>'Pro tento plugin není potřeba žádné připojení.','Open settings'=>'Otevřít nastavení','You do not have permission to change these settings.'=>'Nemáte oprávnění ke změně těchto nastavení.','Settings sections'=>'Sekce nastavení','Support'=>'Podpora','Save changes'=>'Uložit změny','Tools'=>'Nástroje','Export settings'=>'Export nastavení','Reset to defaults'=>'Obnovit výchozí nastavení','This puts every setting on this plugin back to its default. Continue?'=>'Tímto se všechna nastavení tohoto pluginu vrátí na výchozí hodnoty. Pokračovat?','Diagnostics for support'=>'Diagnostika pro podporu','Import a settings file'=>'Importovat soubor nastavení','Import'=>'Importovat','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Exportované soubory nikdy neobsahují hesla, tokeny ani klíče API – na novém webu je budete muset zadat znovu.','Settings saved.'=>'Nastavení uložena.','Every setting on this plugin is back to its default.'=>'Všechna nastavení tohoto pluginu byla obnovena na výchozí hodnoty.','Done.'=>'Hotovo.','That action is not available.'=>'Tato akce není k dispozici.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Tento soubor se nepodařilo přečíst. Zvolte soubor nastavení exportovaný z pluginu Zinn®.','That file is too large to be a settings export.'=>'Tento soubor je příliš velký na to, aby byl exportem nastavení.','That file is not a Zinn® settings export.'=>'Tento soubor není exportem nastavení Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Tento soubor byl exportován z jiného modulu (%s), takže jeho importem by se uložilo nastavení, kterému tento modul nerozumí.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d nastavení importováno. Hesla a klíče API se nikdy neexportují, takže je zadejte znovu.' . "\0" . '%d nastavení importováno. Hesla a klíče API se neexportují, proto je zadejte znovu.' . "\0" . '%d nastavení importováno. Hesla a klíče API se neexportují, proto je zadejte znovu.' . "\0" . '%d nastavení importováno. Hesla a klíče API se neexportují, proto je zadejte znovu.','Translate'=>'Přeložit','Manual overrides'=>'Manuální přepsání','Sitemaps and URLs'=>'Mapy stránek a URL','General'=>'Obecné','Who pays for the translation'=>'Kdo platí za překlad','Either your Zinn Digital® plan, or an API key of your own. There is no free tier — somebody pays a provider for every word.'=>'Buď váš tarif Zinn Digital®, nebo váš vlastní klíč API. Neexistuje žádná bezplatná úroveň – za každé slovo platí poskytovateli někdo jiný.','My Zinn Digital® plan'=>'Můj plán u Zinn Digital®','My own provider key'=>'Můj vlastní klíč poskytovatele','Site ID'=>'ID webu','From your Zinn Digital® dashboard, on this site\'s Translation tab.'=>'Z vašeho řídicího panelu Zinn Digital® na kartě Překlad tohoto webu.','Site token'=>'Token webu','Provider'=>'Poskytovatel','API key'=>'API klíč','Your key, billed to you by the provider. It is stored on this site and sent only to them.'=>'Váš klíč, který vám účtuje poskytovatel. Je uložen na tomto webu a odesílá se pouze jemu.','Model'=>'Model','Leave empty for the cheapest model that does the job well.'=>'Nechte prázdné pro nejlevnější model, který dobře poslouží.','This site is written in'=>'Tento web je napsán v','Leave empty to use the site language from WordPress settings.'=>'Ponechte prázdné pro použití jazyka webu z nastavení WordPress.','Languages to publish'=>'Jazyky k publikování','Each one gets its own web addresses and its own sitemap. Publish only the languages you want indexed.'=>'Každý z nich získá vlastní webové adresy a vlastní soubor sitemap. Publikujte pouze ty jazyky, které chcete mít indexované.','Translate automatically when I publish or update'=>'Přeložit automaticky při publikování nebo aktualizaci','Editing a page marks its translations out of date and they are remade in the background. Editing without changing any words costs nothing.'=>'Úprava stránky označí její překlady za zastaralé a ty se vytvoří znovu na pozadí. Úprava bez změny jakýchkoli slov nestojí nic.','What gets translated'=>'Co se přeloží','Post types'=>'Typy příspěvků','Translate the web addresses too'=>'Přeložte také webové adresy','French visitors get /fr/a-propos/ rather than /fr/about/. The untranslated address keeps working and redirects, so nothing that was indexed breaks.'=>'Francouzští návštěvníci budou přesměrováni na /fr/a-propos/ namísto /fr/about/. Nepřeložená adresa bude nadále fungovat a provede přesměrování, takže nic, co již bylo indexováno, se neporouchá.','Translate SEO titles, descriptions and image alt text'=>'Přeložte SEO titulky, popisy a alt texty obrázků','Translate categories and tags'=>'Přeložit kategorie a štítky','Translate navigation menus'=>'Přeložit navigační menu','Translate WooCommerce products and attributes'=>'Přeložit produkty a atributy WooCommerce','Short descriptions, purchase notes, attribute labels and variation descriptions. Prices, SKUs and stored option values are never touched.'=>'Krátké popisy, nákupní poznámky, štítky atributů a popisy variant. Ceny, SKU a uložené hodnoty možností zůstávají nedotčeny.','SEO'=>'SEO','Add hreflang tags'=>'Přidat značky hreflang','Tells search engines these pages are the same page in different languages. Leave this on unless another plugin is already doing it.'=>'Říká vyhledávačům, že tyto stránky jsou stejnou stránkou v různých jazycích. Nechte toto zapnuté, pokud to již nedělá jiný plugin.','Publish a sitemap for each language'=>'Publikujte sitemapu pro každý jazyk','Publish llms.txt for each language'=>'Publikovat llms.txt pro každý jazyk','A plain-text map of the site that AI answer engines read. They often cannot run JavaScript and may never fetch a sitemap.'=>'Textová mapa webu, kterou čtou vyhledávací moduly s umělou inteligencí. Často nedokážou spouštět JavaScript a sitemapu nemusí nikdy načíst.','Language switcher'=>'Přepínač jazyka','Style'=>'Styl','Colours, spacing and corners are on the Styling tab. Place it with the block, the [zinn_language_switcher] shortcode, or a menu.'=>'Barvy, řádkování a rohy se nacházejí na kartě Vzhled. Umístěte jej pomocí bloku, shortcodu [zinn_language_switcher] nebo menu.','Show only these languages'=>'Zobrazit pouze tyto jazyky','Leave empty to show every language you publish.'=>'Ponechte prázdné pro zobrazení každého jazyka, který publikujete.','Name each language in its own language'=>'Pojmenujte každý jazyk v jeho vlastním jazyce','Deutsch rather than German. Somebody who cannot read the current page cannot read "German" either.'=>'Deutsch místo German. Někdo, kdo neumí přečíst aktuální stránku, nedokáže přečíst ani „German“.','Show flags'=>'Zobrazit příznaky','Off by default: a language is not a country, and Arabic and Spanish have no single flag that does not exclude most of their speakers.'=>'Ve výchozím stavu vypnuto: jazyk není země a arabština ani španělština nemají jedinou vlajku, která by nevylučovala většinu jejich mluvčích.','Include the language being read'=>'Zahrnout čtený jazyk','Include the original language'=>'Zahrnout původní jazyk','Add it to this menu'=>'Přidat do této nabídky','Only the menu you name here. Nothing is added to any other menu on the site.'=>'Zobrazí se pouze nabídka, kterou zde pojmenujete. K žádné jiné nabídce na webu nebude nic přidáno.','Accent'=>'Styl','Background'=>'Pozadí','Text'=>'Text','Corner radius'=>'Poloměr rohu','Spacing'=>'Odsazení','Text size'=>'Velikost textu','Do not add it to a menu'=>'Nepřidávat do nabídky','Edit any translation here. An edited translation is kept exactly as you wrote it and is never overwritten when the page is translated again.'=>'Zde můžete upravit jakýkoliv překlad. Upravený překlad zůstane přesně tak, jak jste jej napsali, a nikdy nebude přepsán při dalším překladu stránky.','Every language'=>'Každý jazyk','Search translations'=>'Hledat překlady','Filter'=>'Filtrovat','Content'=>'Obsah','Language'=>'Jazyk','Translation'=>'Překlad','Status'=>'Stav','Save'=>'Uložit','Nothing translated yet. Publish a language and translation starts in the background.'=>'Zatím nebylo nic přeloženo. Publikujte jazyk a překlad se spustí na pozadí.','These addresses are live. Open any of them to check it, and submit the sitemap index to Google Search Console.'=>'Tyto adresy jsou aktivní. Otevřete kteroukoli z nich a zkontrolujte ji, a odešlete index sitemap do nástroje Google Search Console.','You are not allowed to edit translations on this site.'=>'Nemáte oprávnění upravovat překlady na tomto webu.','Edited by you — kept'=>'Upraveno vámi — ponecháno','Source changed — will be redone'=>'Zdroj se změnil – bude přepracován','Up to date'=>'Aktuální','Connected'=>'Připojeno','Connecting…'=>'Připojování…','Connected, but something needs attention'=>'Připojeno, ale některé položky vyžadují pozornost','Not connected'=>'Nepřipojeno','Running on your own account'=>'Běží na vašem účtu','We could not check this'=>'To se nám nepodařilo ověřit','This plugin did not say why. Send a diagnostics report and we will look.'=>'Tento doplněk neuvedl důvod. Odešlete diagnostickou zprávu a podíváme se na to.','Connection status'=>'Stav připojení','Last checked %s ago.'=>'Naposledy zkontrolováno před %s.','(opens in a new tab)'=>'(otevře se na nové kartě)','Send this to Zinn® support'=>'Odeslat na podporu Zinn®','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Přesně toto bude odesláno – nic jiného a nic skrytého. Vaše hesla, tokeny a klíče API v tom nejsou obsaženy.','The diagnostics report that will be sent'=>'Diagnostická zpráva, která bude odeslána','Copy to clipboard'=>'Kopírovat do schránky','Send this report to Zinn® support'=>'Odeslat tuto sestavu na podporu Zinn®','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Vytvoříme pro vás tiket podpory a odpovíme vám e-mailem. Pokud ho raději nechcete odesílat, zkopírujte ho výše a vložte si jej do tiketu sami.','Copied'=>'Zkopírováno','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Zinn Digital® se nepodařilo z tohoto serveru (%s) kontaktovat. Zkopírujte výše uvedenou zprávu a raději otevřete tiket – ve vašem nastavení není nic špatně.','Sent. Zinn® support has your report and will reply by email.'=>'Podpora Zinn® obdržela vaše hlášení a odpoví vám e-mailem.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Podpora Zinn® eviduje vaše hlášení – referenční číslo %s – a odpoví vám e-mailem.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Odeslali jste několik hlášení v krátké době. Počkejte několik minut a zkuste to znovu – ty předchozí dorazily.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® nyní nemohl zprávu přijmout – chyba je na naší straně, nikoli vaší. Zkuste to brzy znovu nebo zkopírujte výše uvedenou zprávu do ticketu.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Zpráva byla odmítnuta (HTTP %d). Zkopírujte ji výše a otevřete tiket s uvedením tohoto čísla.','%s — guides and services'=>'%s – návody a služby','User guides'=>'Uživatelské příručky','Read the %s user guide'=>'Přečtěte si uživatelskou příručku %s','Hide this'=>'Skrýt toto','Zinn® hosting for WordPress'=>'Hosting Zinn® pro WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, denní zálohy, bezplatná migrace a ovládací panel vytvořený pro lidi, kteří spravují více než jeden web.','The Zinn® marketplace'=>'Tržiště Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Nakupujte a prodávejte zaběhnuté weby, domény a umístění odkazů s penězi bezpečně uschovanými, dokud nebudou obě strany spokojené.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — najměte si lidi, kteří se tím živí','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Náš globální trh pro na volné noze: procházejte více než 10 000 hotových služeb od spisovatelů, designérů, vývojářů a specialistů na SEO, nebo zadejte projekt a nechte je přihazovat.','The API key was rejected. Check that it is still valid and has translation access, then save it again.'=>'Klíč API byl odmítnut. Zkontrolujte, zda je stále platný a má přístup k překladům, a poté jej znovu uložte.','The provider refused on billing or quota. Nothing was translated. Check the balance and limits on your account with them.'=>'Poskytovatel požadavek odmítl kvůli fakturaci nebo kvótě. Nic nebylo přeloženo. Zkontrolujte zůstatek a limity na svém účtu u nich.','The translation provider is having a problem at their end. Nothing was translated or charged, and it will try again on the next pass.'=>'Poskytovatel překladu má na své straně problém. Nic nebylo přeloženo ani naúčtováno a pokus se opakuje při příštím průchodu.','The translation request failed and we could not tell why. Nothing was saved.'=>'Požadavek na překlad selhal a nepodařilo se zjistit proč. Nic nebylo uloženo.','Sitemap index'=>'Index sitemapů','%s sitemap'=>'%s sitemap','LLM content map'=>'Mapa obsahu AI','%s LLM content map'=>'%s Mapa obsahu LLM','Languages published'=>'Zveřejněné jazyky','Site language'=>'Jazyk webu','SEO plugin'=>'SEO plugin','No translation provider is set up yet.'=>'Zatím není nastaven žádný poskytovatel překladů.','Paste an API key from your chosen provider, or connect the site to a Zinn Digital® account, and translation starts on the next pass.'=>'Vložte API klíč od vámi zvoleného poskytovatele nebo propojte web s účtem Zinn Digital® a překlad začne při příštím průchodu.','Translating with your own %s key.'=>'Překlad pomocí vlastního klíče %s.','This site is not connected to a Zinn Digital® account, which is fine — your provider bills you directly.'=>'Tento web není připojen k účtu Zinn Digital®, což je v pořádku – váš poskytovatel vám fakturuje přímo.','Not connected to Zinn Digital® yet.'=>'Zatím nejste připojeni k Zinn Digital®.','Add this site\'s ID and token from your Zinn Digital® dashboard, or switch to your own provider key to run without an account.'=>'Přidejte ID a token tohoto webu ze své nástěnky Zinn Digital® nebo přepněte na vlastní klíč poskytovatele a spusťte jej bez účtu.','Connected to Zinn Digital®.'=>'Připojeno k Zinn Digital®.','The translation provider is having a problem.'=>'Poskytovatel překladu má problém.','Translation is paused — your provider needs attention.'=>'Překlad je pozastaven – váš poskytovatel vyžaduje pozornost.','Translation has not been set up yet.'=>'Překlad ještě nebyl nastaven.','Something went wrong at our end.'=>'Něco se pokazilo na naší straně.','Check their status page'=>'Zkontrolujte jejich stavovou stránku','Fix this on your account'=>'Opravte to na svém účtu','Style preset'=>'Styl předvolby','A starting point. Anything below overrides it.'=>'Výchozí bod. Cokoliv níže má před ním přednost.','Use my own colours and sizes'=>'Použít vlastní barvy a velikosti','Leave this off and the preset is used exactly as it is.'=>'Nechte toto vypnuté a předvolba se použije přesně tak, jak je.','Zinn® language switcher'=>'Jazykový přepínač Zinn®','Let visitors read this page in another language.'=>'Umožněte návštěvníkům číst tuto stránku v jiném jazyce.','Title'=>'Název','Use the plugin setting'=>'Použít nastavení pluginu','Dropdown'=>'Rozbalovací seznam','Inline list'=>'Vložený seznam','Pills'=>'Štítky','Minimal text'=>'Minimální text','Flags and names'=>'Příznaky a názvy','Stacked list'=>'Seznam pod sebou','Choose a language'=>'Zvolte jazyk','See the Zinn Digital® release notes.'=>'Prohlédněte si poznámky k vydání Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Stažená aktualizace neprošla kontrolou integrity a nebyla nainstalována.','No DeepL API key is saved, so there is nothing to translate with.'=>'Není uložen žádný klíč rozhraní DeepL API, takže není co překládat.','DeepL does not translate into %s. Choose Google Gemini or OpenAI for this language, or connect the site to Zinn Digital®.'=>'DeepL nepřekládá do jazyka %s. Zvolte pro tento jazyk Google Gemini nebo OpenAI, nebo připojte web k Zinn Digital®.','DeepL could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'K uslužbě DeepL se nepodařilo připojit. Nic nebylo přeloženo a nebyly účtovány žádné poplatky; pokus se opakuje při dalším průběhu.','Your DeepL character quota is used up for this period. Translation resumes when it resets, or when you raise the limit on your DeepL account.'=>'Vaše kvóta znaků pro DeepL je pro toto období vyčerpána. Překládání bude obnoveno po jejím resetování nebo po navýšení limitu na vašem účtu DeepL.','DeepL answered with something we could not read. Nothing was saved.'=>'Služba DeepL odpověděla způsobem, který nebylo možné přečíst. Nic nebylo uloženo.','No Google Gemini API key is saved, so there is nothing to translate with.'=>'Není uložen žádný klíč rozhraní Google Gemini API, takže není co překládat.','Google Gemini could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'Službu Google Gemini se nepodařilo kontaktovat. Nic nebylo přeloženo ani účtováno; pokus bude zopakován v dalším průchodu.','No OpenAI API key is saved, so there is nothing to translate with.'=>'Není uložen žádný klíč OpenAI API, takže není k dispozici nic, čím by se dalo překládat.','OpenAI could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'OpenAI nebylo možné kontaktovat. Nic nebyło přeloženo a nic nebyło účtováno; pokus se opakuje v dalším kroku.','This site is not connected to Zinn Digital®, so there is nothing to collect. Add the Site ID and token, or switch to your own provider key.'=>'Tento web není propojen se službou Zinn Digital®, takže zde není nic ke shromáždění. Přidejte ID webu a token nebo přepněte na svůj vlastní klíč poskytovatele.','This site is not connected to Zinn Digital®.'=>'Tento web není spojen se společností Zinn Digital®.','Zinn Digital® could not be reached. Nothing was sent; it will try again on the next pass.'=>'Zinn Digital® nebylo možné kontaktovat. Nic nebylo odesláno; další pokus proběhne při příštím průchodu.','Translation is paused on this site. Check the account is up to date on your Zinn Digital® dashboard.'=>'Překlad je na tomto webu pozastaven. Zkontrolujte na svém řídicím panelu Zinn Digital®, zda je účet aktuální.','Zinn Digital® rejected this site\'s token. Copy it again from the site\'s Translation tab on your dashboard.'=>'Zinn Digital® odmítl token tohoto webu. Zkopírujte jej znovu z karty Překlad na svém panelu webu.','Zinn Digital® could not be reached. Your site keeps serving the translations it already has.'=>'Zinn Digital® nebylo možné kontaktovat. Váš web nadále používá již uložené překlady.','Zinn Digital® answered with something we could not read. Your site keeps serving the translations it already has.'=>'Zinn Digital® odpověděl něčím, co nebylo možné přečíst. Váš web nadále poskytuje překlady, které již má.']];